settings.custom_liquid:
{% for collection in collections %}
{% if product.vendor == collection.title %}
<p class="product__text caption-with-letter-spacing"><a href="{{ collection.url }}">{{ 
product.vendor }}</a></p>
{% endif %}
{% endfor %}


<!-- Product Title Without Maker -->
{% assign title = product.title | split: " by " %}
{% assign title = title[0] | split: " Enamel " %}
<h1 class="product__title">{{ title[0] }} {{ title[1] }}</h1>

<div class="reviews-price">

{% assign title = product.title | split: " " %}

{% if product.metafields.custom.bundle != blank %}
{% for pin in product.metafields.custom.bundle.value %}
{% for variant in pin.variants %}
{% if title[0] == variant.title %}
<p>

{% if pin.vendor != "–" %}
<strong>Maker:</strong> {% for collection in collections %}{% if collection.title == pin.vendor %}<a href="{{ collection.url }}">{{ pin.vendor }}</a>{% endif %}{% endfor %}<br>
{% endif %}

<strong>Dimensions:</strong> {{ variant.metafields.custom.width.value }} x {{ variant.metafields.custom.height.value }}<br>

{% if title[0] == variant.title %}
{% endif %}

<strong>Type:</strong> {% for type in variant.metafields.custom.type.value %}{{ type }}{% unless forloop.last %}, {% endunless %}{% endfor %}<br>

<strong>Plating:</strong> {% for plating in variant.metafields.custom.plating.value %}{{ plating }}{% unless forloop.last %}, {% endunless %}{% endfor %}<br>

<strong>Colors:</strong> {% for colors in variant.metafields.custom.colors.value %}{{ colors }}{% unless forloop.last %}, {% endunless %}{% endfor %}<br>

<strong>Posts:</strong> {{ variant.metafields.custom.posts }}<br>

<strong>Clutch:</strong> {{ variant.metafields.custom.clutch }}

</p>
{% endif %}
{% endfor %}
{% endfor %}
{% endif %}
